mal(self.softStealRadius)         local inRange = dist and dist <= self.softStealRadius         if inRange or (self.softStealLatched and self:isCarrying()) then             return "AUTO CARRY", self.softStealSpeed         end     end     if self.laggerMode == 1 then return "LAGGER", self.laggerSpeed end     if self.laggerMode == 2 then return "LAGGER CARRY", self.laggerCarrySpeed end     if self.speedToggled then return "CARRY", self.carrySpeed end     return "NORMAL", self.normalSpeed end  local function destroyLV()     if CarrySystem._lvBoost and CarrySystem._lvBoost.Parent then pcall(function() CarrySystem._lvBoost:Destroy() end) end     if CarrySystem._lvAtt and CarrySystem._lvAtt.Parent then pcall(function() CarrySystem._lvAtt:Destroy() end) end     CarrySystem._lvBoost = nil; CarrySystem._lvAtt = nil end  local function setupLV(hrp)     if CarrySystem._lvBoost and CarrySystem._lvBoost.Parent == hrp then return end     destroyLV()     local att = Instance.new("Attachment"); att.Parent = hrp     local lv = Instance.new("LinearVelocity")     lv.Name = "CarryBoostLV"     lv.Attachment0 = att     lv.VelocityConstraintMode = Enum.VelocityConstraintMode.Plane     lv.PrimaryTangentAxis = _V3new(1,0,0)     lv.SecondaryTangentAxis = _V3new(0,0,1)     lv.MaxForce = CarrySystem._maxForce     lv.PlaneVelocity = Vector2.zero     lv.RelativeTo = Enum.ActuatorRelativeTo.World     lv.Parent = hrp     CarrySystem._lvAtt = att     CarrySystem._lvBoost = lv     pcall(function() hrp:SetNetworkOwner(LP) end) end  function CarrySystem:scanSoftStealAnimals()     self._softStealAnimals = {}     local plots = Workspace:FindFirstChild("Plots")     if not plots then return end     for _, plot in ipairs(plots:GetChildren()) do         if plot:IsA("Model") then             local podiums = plot:FindFirstChild("AnimalPodiums")             if podiums then                 for _, podium in ipairs(podiums:GetChildren()) do                     if podium:IsA("Model") then                         local base = podium:FindFirstChild("Base")                         local spawn = base and base:FindFirstChild("Spawn")                         if spawn then                             table.insert(self._softStealAnimals, {                                 plot = plot.Name,                                 slot = podium.Name,                                 worldPosition = spawn.Position,                                 uid = plot.Name .. "_" .. podium.Name,                             })                         end                     end                 end             end         end     end end  function CarrySystem:startSoftStealScanner()     if self._softStealScanner then return end     self._softStealScanning = true     self:scanSoftStealAnimals()     self._softStealScanner = RunService.Heartbeat:Connect(function()         if not self._softStealScanning then return end         self:scanSoftStealAnimals()     end) end  function CarrySystem:stopSoftStealScanner()     self._softStealScanning = false     if self._softStealScanner then         self._softStealScanner:Disconnect()         self._softStealScanner = nil     end end  function CarrySystem:getNearestSoftStealAnimal(radius)     local char = LP.Character     local root = char and (char:FindFirstChild("HumanoidRootPart") or char:FindFirstChild("UpperTorso"))     if not root then return nil, _huge end     local best, bestDist = nil, _huge     local animals = self._softStealAnimals     local rpos = root.Position     for i = 1, #animals do         local data = animals[i]         if data.worldPosition then             local dx = rpos.X - data.worldPosition.X             local dy = rpos.Y - data.worldPosition.Y             local dz = rpos.Z - data.worldPosition.Z             local dist = _sqrt(dx*dx + dy*dy + dz*dz)             if dist < bestDist then                 best = data; bestDist = dist             end         end     end     if radius and bestDist > radius then return nil, bestDist end     return best, bestDist end  function CarrySystem:updateMovement(dt)     local char = LP.Character     if not char then return end     local hrp = char:FindFirstChild("HumanoidRootPart")     local hum = char:FindFirstChildOfClass("Humanoid")     if not hrp or not hum then return end      local speed = self:getActiveSpeed()     local moveDir = hum.MoveDirection     local moving = moveDir.Magnitude > 0.1      local wallNormalFlat = nil     if moving then         if not self._rayParams then             self._rayParams = _RayParams_new()             self._rayParams.FilterType = Enum.RaycastFilterType.Exclude             self._rayFilter = {}             self._rayFilterTime = 0         end         local now = _tick()         if now - self._rayFilterTime > 1 then             self._rayFilterTime = now             local filter = self._rayFilter             while #filter > 0 do filter[#filter] = nil end             filter[1] = char             local plist = _GetPlayersCached()             for i = 1, #plist do                 local p = plist[i]                 if p.Character then                     filter[#filter + 1] = p.Character                 end             end             self._rayParams.FilterDescendantsInstances = filter         else             local filter = self._rayFilter             local found = false             for i = 1, #filter do                 if filter[i] == char then found = true; break end             end             if not found then                 filter[1] = char                 self._rayParams.FilterDescendantsInstances = filter             end         end         local flatDir = _V3new(moveDir.X, 0, moveDir.Z).Unit         local hit = Workspace:Raycast(hrp.Position + _V3new(0,1,0), flatDir * 2.5, self._rayParams)         if hit and hit.Instance and hit.Instance.CanCollide then             local nf = _V3new(hit.Normal.X, 0, hit.Normal.Z)             if nf.Magnitude > 0.7 then wallNormalFlat = nf.Unit end         end     end      local hVel = _V3new(hrp.AssemblyLinearVelocity.X, 0, hrp.AssemblyLinearVelocity.Z)     local blocked = wallNormalFlat ~= nil or (moving and hVel.Magnitude < 2)      if blocked then         for _, model in ipairs(char:GetChildren()) do             if model:IsA("Model") then                 for _, part in ipairs(model:GetDescendants()) do                     if part:IsA("BasePart") and part.CanCollide then part.CanCollide = false end                 end             end         end         for _, name in ipairs({"Carrying","IsCarrying","Grabbed","Holding","StealHold","HasGrab"}) do             local v = char:FindFirstChild(name)             if v and v:IsA("ObjectValue") and v.Value and v.Value:IsA("Model") then                 for _, part in ipairs(v.Value:GetDescendants()) do                     if part:IsA("BasePart") and part.CanCollide then part.CanCollide = false end                 end             end         end     end      local state = hum:GetState()     local ragdolled = state == Enum.HumanoidStateType.Physics                    or state == Enum.HumanoidStateType.Ragdoll                    or state == Enum.HumanoidStateType.FallingDown     local moverBlocked = ragdolled or self._dropInProgress or self._batAimbotToggled      if not moverBlocked then         if not CarrySystem._lvBoost or CarrySystem._lvBoost.Parent ~= hrp then setupLV(hrp) end         local lv = CarrySystem._lvBoost         if lv then             if not lv.Enabled then lv.Enabled = true end             if moveDir.Magnitude > 0.1 then                 local flat = _V3new(moveDir.X, 0, moveDir.Z).Unit                 if wallNormalFlat then                     local wanted = flat * speed                     local along = wanted - wallNormalFlat * wanted:Dot(wallNormalFlat)                     if along.Magnitude < 0.5 then                         lv.PlaneVelocity = Vector2.zero                     else                         lv.PlaneVelocity = Vector2.new(along.X, along.Z)                     end                 else

